import http from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFile, mkdir, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const styles = await readFile(join(root, 'public', 'styles.css'));
const defaultFile = join(root, 'data', 'books.json');

const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
})[char]);

function layout(title, content) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f4ed"><title>${escapeHtml(title)} · Bookside</title><link rel="stylesheet" href="/styles.css"></head><body><div class="site"><header class="site-header"><a class="brand" href="/" aria-label="Bookside home"><span class="brand-icon" aria-hidden="true">▥</span> bookside<span class="brand-dot">.</span></a><span class="header-note">A little place for your books</span></header>${content}<footer class="site-footer"><span>Bookside</span><span>Keep the stories close.</span></footer></div></body></html>`;
}

function bookCard(book) {
  return `<a class="book-card" href="/books/${encodeURIComponent(book.id)}"><span class="book-spine" aria-hidden="true"></span><span class="card-body"><span class="card-label">${book.finished ? 'FINISHED' : 'READING NOW'}</span><strong class="card-title">${escapeHtml(book.title)}</strong><span class="card-author">by ${escapeHtml(book.author)}</span><span class="card-bottom"><span>View book</span><span aria-hidden="true">↗</span></span></span></a>`;
}

function home(books) {
  const reading = books.filter((book) => !book.finished);
  const finished = books.filter((book) => book.finished);
  return layout('Your bookshelf', `<main><section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="eyebrow-line"></span> YOUR PERSONAL BOOKSHELF</span><h1>Every good story<br>starts <em>somewhere.</em></h1><p>A quiet space to keep track of the books you’re reading, the ones you’ve loved, and the thoughts worth holding onto.</p><a class="hero-link" href="#add-book">Add a book <span aria-hidden="true">↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="art-orbit art-orbit-one"></div><div class="art-orbit art-orbit-two"></div><div class="art-sun"></div><div class="art-book art-book-back"></div><div class="art-book art-book-front"><span></span><span></span><span></span></div><div class="art-caption">ONE PAGE AT A TIME <span>✳</span></div></div></section><div class="shelf-content"><section class="shelf-section" aria-labelledby="reading-title"><div class="section-heading"><div><span class="section-kicker">01 / IN PROGRESS</span><h2 id="reading-title">Currently reading <span class="count">${reading.length}</span></h2></div></div>${reading.length ? `<div class="book-grid">${reading.map(bookCard).join('')}</div>` : `<div class="empty-state"><span class="empty-icon" aria-hidden="true">✳</span><div><strong>Nothing on the nightstand yet.</strong><p>Add a book below to start your reading list.</p></div></div>`}</section><section class="shelf-section" aria-labelledby="finished-title"><div class="section-heading"><div><span class="section-kicker">02 / THE ARCHIVE</span><h2 id="finished-title">Finished books <span class="count">${finished.length}</span></h2></div></div>${finished.length ? `<div class="book-grid">${finished.map(bookCard).join('')}</div>` : `<div class="empty-state"><span class="empty-icon" aria-hidden="true">✓</span><div><strong>Your finished shelf is waiting.</strong><p>Books you finish will find a home here.</p></div></div>`}</section><section id="add-book" class="add-section" aria-labelledby="add-title"><div class="add-intro"><span class="section-kicker">03 / A NEW CHAPTER</span><h2 id="add-title">Add to your <em>shelf.</em></h2><p>What are you reading? Give it a spot here, and add any notes you want to remember.</p><div class="add-decoration" aria-hidden="true">✳</div></div><form class="book-form" action="/books" method="post"><label for="title">Book title <span>*</span></label><input id="title" name="title" type="text" placeholder="e.g. The Secret History" maxlength="200" required><label for="author">Author <span>*</span></label><input id="author" name="author" type="text" placeholder="e.g. Donna Tartt" maxlength="200" required><label for="notes">Your notes <span class="optional">(optional)</span></label><textarea id="notes" name="notes" placeholder="A thought, a quote, a feeling…" maxlength="10000" rows="4"></textarea><button class="primary-button" type="submit">Add book <span aria-hidden="true">↗</span></button></form></section></div></main>`);
}

function detail(book) {
  return layout(book.title, `<main class="detail-main"><a class="back-link" href="/">← &nbsp; Back to bookshelf</a><div class="detail-layout"><div class="detail-cover" aria-hidden="true"><div class="detail-cover-inner"><span class="cover-top">BOOKSIDE / YOUR LIBRARY</span><span class="cover-ornament">✳</span><span class="cover-bottom">A STORY TO KEEP</span></div></div><div class="detail-content"><span class="section-kicker">${book.finished ? 'FROM THE ARCHIVE' : 'ON YOUR NIGHTSTAND'}</span><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by <strong>${escapeHtml(book.author)}</strong></p><span class="status-pill ${book.finished ? 'status-finished' : ''}"><span class="status-dot"></span>${book.finished ? 'Finished' : 'Currently reading'}</span><div class="detail-divider"></div><div class="notes-block"><span class="section-kicker">YOUR NOTES</span>${book.notes ? `<p class="notes-text">${escapeHtml(book.notes)}</p>` : `<p class="notes-empty">No notes yet for this book.</p>`}</div><div class="detail-actions">${book.finished ? '' : `<form action="/books/${encodeURIComponent(book.id)}/finish" method="post"><button class="primary-button" type="submit">Mark as finished <span aria-hidden="true">✓</span></button></form>`}<button class="secondary-button" type="button" id="copy-link">Copy book link <span aria-hidden="true">↗</span></button></div><p class="share-hint">Share this page’s link to show someone this book.</p></div></div></main><script>document.getElementById('copy-link').addEventListener('click', async function () { try { await navigator.clipboard.writeText(location.href); this.firstChild.textContent = 'Link copied '; } catch { this.firstChild.textContent = 'Copy the URL above '; } });</script>`);
}

async function load(file) {
  try { return JSON.parse(await readFile(file, 'utf8')); }
  catch (error) { if (error.code === 'ENOENT') return []; throw error; }
}

async function save(file, books) {
  await mkdir(dirname(file), { recursive: true });
  const temp = `${file}.${randomUUID()}.tmp`;
  try {
    await writeFile(temp, JSON.stringify(books, null, 2) + '\n');
    await rename(temp, file);
  } catch (error) {
    // Do not replace a good bookshelf if writing fails.
    const { rm } = await import('node:fs/promises');
    await rm(temp, { force: true });
    throw error;
  }
}

function send(res, status, body, type = 'text/html; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(body);
}
function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}
function errorPage(status, message) {
  return layout(message, `<main class="error-page"><span class="section-kicker">${status} / BOOKSIDE</span><h1>${escapeHtml(message)}</h1><p>Let’s get back to the books.</p><a class="primary-button" href="/">Back to bookshelf <span aria-hidden="true">↗</span></a></main>`);
}
async function formBody(req) {
  if (!req.headers['content-type']?.toLowerCase().startsWith('application/x-www-form-urlencoded')) throw Object.assign(new Error('Expected a form submission'), { status: 415 });
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 30000) throw Object.assign(new Error('Form is too large'), { status: 413 });
  }
  return new URLSearchParams(body);
}

export function createApp({ file = defaultFile } = {}) {
  // Serialize read-modify-write operations so concurrent submissions cannot lose books.
  let pending = Promise.resolve();
  function update(fn) {
    const next = pending.then(async () => {
      const books = await load(file);
      const result = fn(books);
      if (result) await save(file, books);
      return result;
    });
    pending = next.catch(() => {});
    return next;
  }
  return http.createServer(async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname;
      if (req.method === 'GET' && pathname === '/styles.css') return send(res, 200, styles, 'text/css; charset=utf-8');
      if (req.method === 'GET' && pathname === '/') return send(res, 200, home(await load(file)));
      if (req.method === 'POST' && pathname === '/books') {
        const form = await formBody(req);
        const title = (form.get('title') || '').trim();
        const author = (form.get('author') || '').trim();
        const notes = (form.get('notes') || '').trim();
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) return send(res, 400, errorPage(400, 'Check your book details'));
        const id = randomUUID();
        await update((books) => { books.unshift({ id, title, author, notes, finished: false }); return true; });
        return redirect(res, `/books/${id}`);
      }
      const finish = pathname.match(/^\/books\/([a-f0-9-]{36})\/finish$/);
      if (req.method === 'POST' && finish) {
        const found = await update((books) => {
          const book = books.find((item) => item.id === finish[1]);
          if (book && !book.finished) { book.finished = true; return true; }
          return book ? 'exists' : false;
        });
        return found ? redirect(res, `/books/${finish[1]}`) : send(res, 404, errorPage(404, 'Book not found'));
      }
      const match = pathname.match(/^\/books\/([a-f0-9-]{36})$/);
      if (req.method === 'GET' && match) {
        const book = (await load(file)).find((item) => item.id === match[1]);
        return book ? send(res, 200, detail(book)) : send(res, 404, errorPage(404, 'Book not found'));
      }
      send(res, 404, errorPage(404, 'Page not found'));
    } catch (error) {
      console.error(error);
      if (!res.headersSent) send(res, error.status || 500, errorPage(error.status || 500, error.status ? error.message : 'Something went wrong'));
      else res.end();
    }
  });
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT || 3000);
  createApp({ file: process.env.BOOKS_FILE || defaultFile }).listen(port, () => console.log(`Bookside is ready at http://localhost:${port}`));
}

