import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createApp } from './server.js';

async function listen(server) {
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return `http://127.0.0.1:${server.address().port}`;
}
async function close(server) {
  await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
}

test('books can be added, viewed by link, finished, and survive restart', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'bookside-'));
  const file = join(dir, 'books.json');
  let server = createApp({ file });
  try {
    let base = await listen(server);
    let response = await fetch(base);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /Currently reading/);

    response = await fetch(`${base}/books`, { method: 'POST', body: new URLSearchParams({ title: 'A <Book>', author: 'Jane & Co.', notes: 'Line one\nLine two' }), redirect: 'manual' });
    assert.equal(response.status, 303);
    const bookPath = response.headers.get('location');
    assert.match(bookPath, /^\/books\/[a-f0-9-]{36}$/);

    response = await fetch(base + bookPath);
    let html = await response.text();
    assert.match(html, /A &lt;Book&gt;/);
    assert.match(html, /Jane &amp; Co\./);
    assert.match(html, /Line one\nLine two/);
    assert.doesNotMatch(html, /A <Book>/);
    assert.match(html, /Mark as finished/);

    response = await fetch(base);
    html = await response.text();
    assert.match(html, /Currently reading <span class="count">1/);
    assert.match(html, /Finished books <span class="count">0/);
    assert.match(html, new RegExp(bookPath));

    response = await fetch(base + bookPath + '/finish', { method: 'POST', redirect: 'manual' });
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), bookPath);
    response = await fetch(base);
    html = await response.text();
    assert.match(html, /Currently reading <span class="count">0/);
    assert.match(html, /Finished books <span class="count">1/);

    await close(server);
    server = createApp({ file });
    base = await listen(server);
    response = await fetch(base + bookPath);
    html = await response.text();
    assert.equal(response.status, 200);
    assert.match(html, /Finished/);
    assert.doesNotMatch(html, /Mark as finished/);
    assert.equal(JSON.parse(await readFile(file, 'utf8'))[0].finished, true);
  } finally {
    if (server.listening) await close(server);
    await rm(dir, { recursive: true, force: true });
  }
});

test('invalid input and missing books are rejected without creating records', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'bookside-'));
  const file = join(dir, 'books.json');
  const server = createApp({ file });
  try {
    const base = await listen(server);
    const bad = await fetch(`${base}/books`, { method: 'POST', body: new URLSearchParams({ title: '   ', author: 'Someone' }) });
    assert.equal(bad.status, 400);
    const missing = await fetch(`${base}/books/00000000-0000-0000-0000-000000000000`);
    assert.equal(missing.status, 404);
    const home = await fetch(base);
    assert.match(await home.text(), /Currently reading <span class="count">0/);
  } finally {
    await close(server);
    await rm(dir, { recursive: true, force: true });
  }
});

